alter table public.schoolpro_admissions add column if not exists first_name text,add column if not exists last_name text,add column if not exists gender text,add column if not exists date_of_birth date,add column if not exists guardian_email text,add column if not exists previous_school text,add column if not exists application_number text,add column if not exists reviewed_by uuid references auth.users(id),add column if not exists reviewed_at timestamptz,add column if not exists admitted_student_id uuid references public.schoolpro_students(id);
create unique index if not exists schoolpro_admissions_application_number_uq on public.schoolpro_admissions(school_id,application_number) where application_number is not null;
create or replace function public.admit_schoolpro_applicant(p_application uuid) returns uuid language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions; sid uuid; adm text;begin select * into a from public.schoolpro_admissions where id=p_application; if a.id is null then raise exception 'Application not found'; end if; if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('owner','proprietor','admin','school_admin')) and not exists(select 1 from public.schoolpro_schools s where s.id=a.school_id and s.owner_id=auth.uid()) then raise exception 'Not authorized'; end if; if a.admitted_student_id is not null then return a.admitted_student_id; end if; adm:=coalesce(a.application_number,'ADM-'||upper(substr(replace(a.id::text,'-',''),1,8))); insert into public.schoolpro_students(school_id,admission_number,first_name,last_name,class_name,gender,guardian_name,guardian_phone,status) values(a.school_id,adm,coalesce(nullif(a.first_name,''),split_part(a.applicant_name,' ',1)),coalesce(nullif(a.last_name,''),nullif(trim(substr(a.applicant_name,length(split_part(a.applicant_name,' ',1))+1)),''),'Student'),coalesce(a.class_applied,'Unassigned'),a.gender,a.guardian_name,a.guardian_contact,'active') returning id into sid; update public.schoolpro_admissions set status='admitted',reviewed_by=auth.uid(),reviewed_at=now(),admitted_student_id=sid where id=a.id; return sid;end$$; revoke all on function public.admit_schoolpro_applicant(uuid) from public,anon;grant execute on function public.admit_schoolpro_applicant(uuid) to authenticated;